// Loaded only via `new Worker(new URL(...))` from app.mjs — no static import
// anywhere. Its exports must NOT be stubbed.
const { parentPort } = require('node:worker_threads');

function times7(n) {
  return n * 7;
}

function unusedWorkerFn(n) {
  return n * 6;
}

exports.times7 = times7;
exports.unusedWorkerFn = unusedWorkerFn;

if (parentPort) {
  parentPort.on('message', (n) => parentPort.postMessage(times7(n)));
}
